import os, re, subprocess, collections

decl_re = re.compile(r'^func\s+(?:\((?P<recv>[^)]*)\)\s+)?(?P<name>[A-Za-z_0-9]+)\s*\(')

decls = []  # (name, path, pkgdir, is_method, exported)
for root, dirs, files in os.walk('internal'):
    for f in files:
        if not f.endswith('.go') or f.endswith('_test.go'):
            continue
        p = os.path.join(root, f)
        for i, line in enumerate(open(p, encoding='utf-8', errors='replace'), 1):
            m = decl_re.match(line)
            if m:
                decls.append((m.group('name'), p, i, root, bool(m.group('recv'))))

# gather all go files
allgo = []
for root, dirs, files in os.walk('.'):
    if '/.git' in root or root.startswith('./.git'):
        continue
    for f in files:
        if f.endswith('.go'):
            allgo.append(os.path.join(root, f))

cache = {}
def lines_of(p):
    if p not in cache:
        cache[p] = open(p, encoding='utf-8', errors='replace').read().split('\n')
    return cache[p]

pkgname = {}
for root, dirs, files in os.walk('internal'):
    for f in files:
        if f.endswith('.go') and not f.endswith('_test.go'):
            first = None
            for line in open(os.path.join(root,f), encoding='utf-8', errors='replace'):
                if line.startswith('package '):
                    first = line.split()[1].strip()
                    break
            if first:
                pkgname[root] = first
            break

results = []
for name, path, ln, pkgdir, is_method in decls:
    exported = name[0].isupper()
    if is_method:
        pat = re.compile(r'\.' + re.escape(name) + r'\s*\(')
        scope = allgo
    elif exported:
        pk = pkgname.get(pkgdir, '')
        pat = re.compile(r'\b' + re.escape(pk) + r'\.' + re.escape(name) + r'\s*\(')
        scope = allgo
    else:
        pat = re.compile(r'(?<![A-Za-z_0-9.])' + re.escape(name) + r'\s*\(')
        scope = [p for p in allgo if os.path.dirname(p) == pkgdir]
    total = 0
    testtotal = 0
    files_hit = collections.Counter()
    for p in scope:
        for i, l in enumerate(lines_of(p), 1):
            if decl_re.match(l):
                continue
            if pat.search(l):
                if p.endswith('_test.go'):
                    testtotal += 1
                else:
                    total += 1
                    files_hit[p] += 1
    results.append((total, testtotal, name, path, ln, is_method, sorted(files_hit.items(), key=lambda x:-x[1])[:5]))

results.sort(key=lambda r: -r[0])
for r in results[:25]:
    print(r[0], '(+%d test)' % r[1], r[2], r[3]+':'+str(r[4]), 'method' if r[5] else 'func')
    for f,c in r[6]:
        print('      ', c, f)
